using System; using Game.Ball; using Game.Targets;
namespace Game.Core { public static class GameEvents { public static event Action OnBallThrown; public static event Action<BallController> OnBallSettled; public static event Action<TargetController> OnTargetHit; public static event Action OnLevelWin; public static event Action OnLevelFail; public static event Action OnRetry; public static void RaiseBallThrown()=>OnBallThrown?.Invoke(); public static void RaiseBallSettled(BallController b)=>OnBallSettled?.Invoke(b); public static void RaiseTargetHit(TargetController t)=>OnTargetHit?.Invoke(t); public static void RaiseLevelWin()=>OnLevelWin?.Invoke(); public static void RaiseLevelFail()=>OnLevelFail?.Invoke(); public static void RaiseRetry()=>OnRetry?.Invoke(); } }
